const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Monte Pisano, Northern Italy
  const montePisano = ee.Geometry.Point([10.5, 43.7]).buffer(10000); // 10km buffer

  // 2. Define date range
  const startDate = '2019-02-24';
  const endDate = '2019-02-27'; // Inclusive end

  console.log('Searching for active fires in Monte Pisano...');
  console.log('Date Range: 2019-02-24 to 2019-02-26');

  // 3. Try MODIS Thermal Anomalies/Fire collection
  let fireCollection = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate(startDate, endDate)
    .filterBounds(montePisano);

  const collectionSize = fireCollection.size().getInfo();
  console.log('MODIS MOD14A1 Images Found: ' + collectionSize);

  if (collectionSize === 0) {
    // Try MYD14A1 (Aqua satellite)
    fireCollection = ee.ImageCollection('MODIS/006/MYD14A1')
      .filterDate(startDate, endDate)
      .filterBounds(montePisano);

    const aquaSize = fireCollection.size().getInfo();
    console.log('MODIS MYD14A1 Images Found: ' + aquaSize);

    if (aquaSize === 0) {
      console.log('No fire detection data available for this period.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Check for fire detections using FireMask band
  const fireMask = fireCollection.select('FireMask').mosaic();

  // FireMask values: 0-6 (no fire), 7-9 (fire with varying confidence)
  const firePixels = fireMask.gte(7);

  // 5. Count fire pixels
  const fireStats = firePixels.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: montePisano,
    scale: 1000,
    maxPixels: 1e9
  });

  const fireCount = fireStats.get('FireMask').getInfo();

  console.log('Fire Pixel Count: ' + fireCount);

  // 6. Check total pixels to ensure valid data
  const totalPixels = fireMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: montePisano,
    scale: 1000,
    maxPixels: 1e9
  }).get('FireMask').getInfo();

  console.log('Total Valid Pixels: ' + totalPixels);

  if (totalPixels === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (fireCount === null || fireCount === undefined) {
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Determine answer
  if (fireCount > 0) {
    console.log('Active fire(s) detected!');
    console.log('<answer>A</answer>');
  } else {
    console.log('No active fires detected.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
